import java.io.File;
import java.util.Random;

public class UniqueFilenameGenerator {

    private static final String PREFIX = "file_";
    private static final long TIMESTAMP_OFFSET = System.currentTimeMillis();
    private static final Random RANDOM = new Random();

    public static File generateUniqueFile(String prefix, int length) {
        // Generate a unique identifier
        String uniqueId = generateUniqueId(length);

        // Combine the prefix with the unique identifier to create a filename
        String fileName = PREFIX + uniqueId;

        // Create a file object using the generated filename
        File file = new File(fileName);

        // Check if the file already exists
        while (file.exists()) {
            // Generate a new unique identifier and try again
            uniqueId = generateUniqueId(length);
            fileName = PREFIX + uniqueId;
            file = new File(fileName);
        }

        return file;
    }

    private static String generateUniqueId(int length) {
        StringBuilder sb = new StringBuilder(length);
        for (int i = 0; i < length; i++) {
            sb.append(RANDOM.nextInt(16));
        }
        return sb.toString();
